<?php if ($remaining>0 && $payment['subscription_id']): ?><form method="post" action="payment_refund?id=<?= (int)$payment['id'] ?>" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_token" value="<?= e($token) ?>"><label>Montant remboursé (DT) *<input type="number" name="amount" min="0.001" max="<?= e(number_format($remaining/1000,3,'.','')) ?>" step="0.001" required value="<?= e(is_string($_POST['amount'] ?? null) ? $_POST['amount'] : '') ?>"></label><label>Motif *<input name="reason" minlength="3" maxlength="500" required value="<?= e(is_string($_POST['reason'] ?? null) ? $_POST['reason'] : '') ?>"></label><p class="form-hint">Le montant remboursé augmente le solde dû de l’abonnement, sans annuler ni modifier celui-ci. Si une annulation ou un accord commercial est nécessaire, traitez-le séparément.</p><div class="form-actions"><button class="primary" data-confirm="Confirmez-vous que ce remboursement a déjà été effectué et doit être enregistré ?" onclick="return confirm(this.dataset.confirm)">Enregistrer le remboursement</button></div></form><?php else: ?><p class="form-hint">Aucun montant remboursable pour un abonnement rattaché.</p><?php endif; ?></section>
